-- DQ-007: HER2 Status Domain---- Purpose:-- Validate the observed values of the HER2.Final.Status-- variable in the staging layer.---- Expected categories:-- - Positive-- - Negative-- - NULL-- - Equivocal-- - Not Available---- Expected record counts:-- - Positive = 86-- - Negative = 457-- - NULL = 145-- - Equivocal = 9-- - Not Available = 8-- - Total records = 705---- This validation does not modify the data.SELECT    "HER2.Final.Status",    COUNT(*) AS quantityFROM staging.brca_sample_wideGROUP BY "HER2.Final.Status"ORDER BY quantity DESC;